class Coin {
  constructor(value) {
    this.value = value;
  }
}

function make(Kind, value) {
  try {
    return Kind(value).value;
  } catch (error) {
    return error.name;
  }
}

console.log(make(Coin, 5));
console.log(make((value) => new Coin(value), 5));
console.log(typeof Coin);
